import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getApiUrl } from '../utils/serverUrl';
const API = getApiUrl();
const emptyQ = () => ({ question:'', options:['','','',''], correctAnswer:0, timeLimit:30, points:100, category:'General', explanation:'' });
export default function AdminMockTestPage(){
  const { user, token } = useAuth(); const navigate=useNavigate();
  const [tab,setTab]=useState('pending'); const [pending,setPending]=useState([]); const [form,setForm]=useState({title:'',description:'',examType:'Competitive Exam',examName:'',subject:'',topic:'',category:'General',difficulty:'Medium',durationMinutes:30,negativeMarking:0,questions:[emptyQ()]});
  const [busy,setBusy]=useState(false); const [message,setMessage]=useState(''); const [error,setError]=useState('');
  const headers={Authorization:`Bearer ${token}`};
  const load=async()=>{try{const r=await axios.get(`${API}/quiz/mocks/pending`,{headers});setPending(r.data.mocks||[]);}catch(e){setError(e.response?.data?.message||'Unable to load pending mocks');}};
  useEffect(()=>{if(user?.role==='admin')load();},[user]);
  if(user?.role!=='admin') return <div style={{padding:'110px 24px'}}><div className="glass-card" style={{maxWidth:600,margin:'auto',padding:30}}><h2>Admin Access Required</h2><button className="btn btn-primary" onClick={()=>navigate('/dashboard')}>Back</button></div></div>;
  const setQ=(qi,k,v)=>setForm(p=>({...p,questions:p.questions.map((q,i)=>i===qi?{...q,[k]:v}:q)}));
  const setOpt=(qi,oi,v)=>setForm(p=>({...p,questions:p.questions.map((q,i)=>i===qi?{...q,options:q.options.map((o,j)=>j===oi?v:o)}:q)}));
  const submit=async(e)=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{await axios.post(`${API}/quiz/mocks`,form,{headers});setMessage('Manual mock test added successfully and is immediately available.');setForm({...form,title:'',description:'',examName:'',subject:'',topic:'',questions:[emptyQ()]});}catch(e){setError(e.response?.data?.message||'Failed to create mock test');}finally{setBusy(false)}};
  const approve=async(id,status)=>{try{await axios.patch(`${API}/quiz/mocks/${id}/approval`,{status},{headers});load();}catch(e){setError(e.response?.data?.message||'Approval update failed');}};
  return <div style={{minHeight:'100vh',padding:'100px 24px 50px'}}><div className="container" style={{maxWidth:1100}}>
    <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,flexWrap:'wrap',marginBottom:20}}><div><span className="badge badge-purple">ADMIN · MOCK TESTS</span><h1 style={{fontFamily:'var(--font-display)',margin:'10px 0 5px'}}>Mock Test Management</h1><p style={{color:'var(--text-secondary)'}}>Approve learner-created mocks and add official mock tests manually.</p></div><button className="btn btn-secondary" onClick={()=>navigate('/dashboard')}>← Dashboard</button></div>
    <div style={{display:'flex',gap:10,marginBottom:20}}><button className={`btn ${tab==='pending'?'btn-primary':'btn-secondary'}`} onClick={()=>setTab('pending')}>⏳ Pending ({pending.length})</button><button className={`btn ${tab==='manual'?'btn-primary':'btn-secondary'}`} onClick={()=>setTab('manual')}>➕ Add Manual Mock</button></div>
    {error&&<div className="glass-card" style={{padding:14,color:'#ff7777',marginBottom:14}}>{error}</div>}{message&&<div className="glass-card" style={{padding:14,color:'#00ff88',marginBottom:14}}>{message}</div>}
    {tab==='pending'?<div style={{display:'grid',gap:14}}>{pending.length===0?<div className="glass-card" style={{padding:28,color:'var(--text-secondary)'}}>No pending mock tests.</div>:pending.map(m=><div className="glass-card" key={m._id} style={{padding:22}}><div style={{display:'flex',justifyContent:'space-between',gap:16,flexWrap:'wrap'}}><div><span className="badge badge-blue">{m.examType}</span><h2 style={{fontFamily:'var(--font-display)',fontSize:'1.25rem',margin:'10px 0'}}>{m.title}</h2><p style={{color:'var(--text-secondary)',margin:0}}>{m.subject}{m.topic?` · ${m.topic}`:''} · {m.questions?.length||0} questions · {m.difficulty}</p><p style={{color:'var(--text-muted)',fontSize:'.82rem'}}>Created by: {m.creator?.username||'User'}</p></div><div style={{display:'flex',gap:8,alignItems:'center'}}><button className="btn btn-primary" onClick={()=>approve(m._id,'approved')}>✓ Approve</button><button className="btn btn-secondary" onClick={()=>approve(m._id,'rejected')}>✕ Reject</button></div></div></div>)}</div>:<form className="glass-card" style={{padding:24}} onSubmit={submit}>
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(220px,1fr))',gap:12}}>{[['title','Title'],['examType','Exam Type'],['examName','Exam Name'],['subject','Subject'],['topic','Topic'],['category','Category']].map(([k,l])=><div className="input-group" key={k}><label className="input-label">{l}</label><input className="input-field" value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})} required={['title','subject'].includes(k)}/></div>)}</div>
      <div className="input-group"><label className="input-label">Description</label><textarea className="input-field" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></div>
      <div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:12}}><select className="input-field" value={form.difficulty} onChange={e=>setForm({...form,difficulty:e.target.value})}><option>Easy</option><option>Medium</option><option>Hard</option><option>Expert</option></select><input className="input-field" type="number" min="5" max="180" value={form.durationMinutes} onChange={e=>setForm({...form,durationMinutes:Number(e.target.value)})}/><input className="input-field" type="number" min="0" max="1" step="0.25" value={form.negativeMarking} onChange={e=>setForm({...form,negativeMarking:Number(e.target.value)})}/></div>
      {form.questions.map((q,i)=><div className="glass-card-sm" style={{padding:16,marginTop:16}} key={i}><div style={{display:'flex',justifyContent:'space-between'}}><strong>Question {i+1}</strong>{form.questions.length>1&&<button type="button" className="btn btn-secondary btn-sm" onClick={()=>setForm(p=>({...p,questions:p.questions.filter((_,j)=>j!==i)}))}>Remove</button>}</div><input className="input-field" style={{marginTop:10}} placeholder="Question" value={q.question} onChange={e=>setQ(i,'question',e.target.value)} required/><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8,marginTop:8}}>{q.options.map((o,j)=><input className="input-field" key={j} placeholder={`Option ${j+1}`} value={o} onChange={e=>setOpt(i,j,e.target.value)} required/>)}</div><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8,marginTop:8}}><select className="input-field" value={q.correctAnswer} onChange={e=>setQ(i,'correctAnswer',Number(e.target.value))}><option value={0}>Correct Option 1</option><option value={1}>Correct Option 2</option><option value={2}>Correct Option 3</option><option value={3}>Correct Option 4</option></select><input className="input-field" type="number" min="5" max="180" value={q.timeLimit} onChange={e=>setQ(i,'timeLimit',Number(e.target.value))}/></div></div>)}
      <div style={{display:'flex',gap:10,marginTop:18}}><button type="button" className="btn btn-secondary" onClick={()=>setForm(p=>({...p,questions:[...p.questions,emptyQ()]}))}>+ Add Question</button><button className="btn btn-primary" disabled={busy}>{busy?'Saving...':'Publish Manual Mock Test'}</button></div>
    </form>}
  </div></div>;
}
